// Keep only what Filter needs (Zendesk tickets carry ~300 custom fields; full search results stalled the task runner in Nova Router).
const CAT = 22865771347348;
const results = $input.all().flatMap(i => i.json.results || []); // v1.4: search is paginated (one item per page)
const slim = results.map(t => ({
  id: t.id, subject: t.subject, group_id: t.group_id, status: t.status, requester_id: t.requester_id,
  created_at: t.created_at, updated_at: t.updated_at, assignee_id: t.assignee_id || null,
  channel: t.via?.channel || null, tags: t.tags || [],
  category: ((t.custom_fields || []).find(f => f.id === CAT) || {}).value || null,
}));
return [{ json: { source: 'ws', results: slim } }];

// Keep only what Filter needs (Zendesk tickets carry ~300 custom fields; full search results stalled the task runner in Nova Router).
const CAT = 22865771347348;
const results = $input.all().flatMap(i => i.json.results || []); // v1.4: search is paginated (one item per page)
const slim = results.map(t => ({
  id: t.id, subject: t.subject, group_id: t.group_id, status: t.status, requester_id: t.requester_id,
  created_at: t.created_at, updated_at: t.updated_at, assignee_id: t.assignee_id || null,
