// Nova Resolver v1.4: scheduled = up to 5 OPEN tickets with a roster owner (WS + CS); backlog (manual) = every new/open
// Worker Support ticket, unassigned included, notes only. Config arrives as an item with source 'config'.
// One pass per ticket: tag nova_res_<yyyymmddhhmm> (UTC). Re-check only when there was activity after our pass
// (beyond our own write) AND at least 4 h passed. Everything comes from the Merge input — no $() lookups.
const A = { justin: 54788295418644, sudu: 24567978777492, jaime: 55350915332244, caro: 32288140085012, cristian: 48493524357268, brisa: 47071350698516, miguel: 28269839522452, samuel: 40230868739348, mike: 42677627758740 };
const N = { justin: 'Justin', sudu: 'Sudu', jaime: 'Jaime', caro: 'Carolina', cristian: 'Cristian', brisa: 'Brisa', miguel: 'Miguel', samuel: 'Samuel', mike: 'Mike' };
const DOMAIN = { justin: 'payouts', sudu: 'payouts', caro: 'card', jaime: 'draft_only', cristian: 'draft_only', brisa: 'draft_only', miguel: 'draft_only', samuel: 'draft_only', mike: 'draft_only' };
const IDS = Object.fromEntries(Object.entries(A).map(([k, v]) => [v, k]));
const CFG = ($input.all().map(i => i.json).find(x => x.source === 'config')) || { mode: 'scheduled', max: 5, auto_send: false };
const BACKLOG = CFG.mode === 'backlog';
const MAX = Number(CFG.max) || 5, REVISIT_H = 4, OWN_WRITE_MIN = 10, MIN_IDLE_MIN = 3;
const now = Date.now();
const stampMs = tg => {
  const s = (tg || []).map(x => /^nova_res_(\d{12})$/.exec(x)).filter(Boolean).map(m => m[1]).sort().pop();
  if (!s) return null;
  return Date.UTC(+s.slice(0, 4), +s.slice(4, 6) - 1, +s.slice(6, 8), +s.slice(8, 10), +s.slice(10, 12));
};
const all = $input.all().filter(i => i.json.source === 'ws' || (!BACKLOG && i.json.source === 'cs')).flatMap(i => i.json.results || []);
const seen = new Set(), out = [];
// payouts first (the only domain where Nova acts), then the rest; newest activity first inside each
const rank = t => (DOMAIN[IDS[t.assignee_id]] === 'payouts' ? 0 : DOMAIN[IDS[t.assignee_id]] === 'card' ? 1 : 2);
all.sort((a, b) => rank(a) - rank(b) || new Date(b.updated_at) - new Date(a.updated_at));
for (const t of all) {
  if (out.length >= MAX) break;
  if (seen.has(t.id)) continue;
  if (!(t.status === 'open' || (BACKLOG && t.status === 'new'))) continue;
  const key = IDS[t.assignee_id] || (BACKLOG ? (t.assignee_id ? 'other' : 'unassigned') : null);
  if (!key) continue; // owner outside the roster (backlog sweep also takes unassigned tickets)
  const tg = t.tags || [];
  if (['nova_resolver_skip', 'closed_by_merge', 'nova_followup_entrega'].some(x => tg.includes(x))) continue; // v1.3: our own delivery follow-ups are not customer asks
  const upd = new Date(t.updated_at).getTime();
  if (now - upd < MIN_IDLE_MIN * 60000) continue; // someone is typing right now
  const st = stampMs(tg);
  if (st) {
    if (upd <= st + OWN_WRITE_MIN * 60000) continue;      // nothing new since our pass
    if (now - st < REVISIT_H * 3600000) continue;          // too soon to look again
  }
  seen.add(t.id);
  out.push({ json: {
    ticket_id: t.id, subject: t.subject, group: t.group_id === 23897889259668 ? 'Company Support' : 'Worker Support',
    requester_id: t.requester_id, channel: t.channel, category: t.category, created_at: t.created_at, updated_at: t.updated_at,
    owner_key: key, owner: N[key] || (key === 'other' ? 'Other agent (' + t.assignee_id + ')' : 'Unassigned'), domain: DOMAIN[key] || 'draft_only', tags: tg,
    mode: CFG.mode, quiet: CFG.quiet === true,
    auto_send: CFG.auto_send === true && (BACKLOG || !['unassigned', 'other'].includes(key)),
    old_stamps: tg.filter(x => /^nova_res_\d{12}$/.test(x)), revisit: !!st,
  }});
}
return out;

parameters.text:
=Prepare this ticket for its owner.

Ticket ID: {{ $json.ticket_id }}
Subject: {{ $json.subject }}
Group: {{ $json.group }}
Owner: {{ $json.owner }} (domain: {{ $json.domain }})
Category tag: {{ $json.category || '(empty)' }}
Requester ID: {{ $json.requester_id }}
Channel: {{ $json.channel }}
Created: {{ $json.created_at }} · Last update: {{ $json.updated_at }}{{ $json.revisit ? '\nNote: Nova already left a note before — focus on what is NEW since its last note.' : '' }}

Skip internal-only tickets: if the ticket has no customer message at all (only internal notes), return answerable=not_enough_info with a one-line ask.
Use your tools, then return ONLY the structured output.

