={{ (() => {
  const d = $json.output || {};
  const tk = $('Loop Over Tickets').item.json || {};
  if (!d.ticket_id || Number(d.ticket_id) !== Number(tk.ticket_id)) return JSON.stringify({ skip: true, error: 'Agent returned no valid result', ticket_id: tk.ticket_id });
  const MSG = ['whatsapp', 'native_messaging', 'sunshine_conversations_api', 'sunshine_conversations_facebook_messenger', 'chat', 'instagram_dm', 'line', 'telegram', 'wechat'];
  const ANS = { yes: '✅ Yes — the draft below answers it', needs_customer_info: '🟡 Needs info from the customer (draft asks for it)', needs_team: '🟠 Needs another team before answering', not_enough_info: '⚪ Not enough information to answer' };
  const TEAM = { payouts: 'Payouts', card: 'Ontop Card / Reserve team', tech: 'Tech / Product', compliance: 'Compliance / R&C', other: 'another team', none: '-' };
  const ch = tk.channel || '';
  const kb = (d.kb_used || []).slice(0, 4).map(k => '  – ' + (k.title || '') + (k.url ? ' (' + k.url + ')' : '')).join('\n');
  // Payouts side conversation: only Justin/Sudu domain, only with confirmed data and high confidence
  const txOk = /\d{5,}/.test(String(d.sc_transaction_ids || ''));
  const scCreate = tk.domain === 'payouts' && d.side_conversation_needed === true && d.sc_team === 'payouts' && d.sc_already_open !== true && d.sc_ready === true && d.confidence === 'high' && txOk && !!d.sc_body;
  const scSuggest = !scCreate && d.side_conversation_needed === true && d.sc_already_open !== true && !!d.sc_body;
  const why = [];
  if (d.side_conversation_needed && !scCreate) {
    if (tk.domain !== 'payouts') why.push('domain ' + tk.domain + ' → suggestion only');
    else {
      if (d.sc_team !== 'payouts') why.push('team is ' + (d.sc_team || '-'));
      if (d.sc_ready !== true) why.push('data not complete');
      if (d.confidence !== 'high') why.push('confidence ' + d.confidence);
      if (!txOk) why.push('no confirmed transaction ID');
    }
  }
  let chLine = '';
  if (MSG.includes(ch)) {
    const last = d.last_customer_message_at ? Date.parse(d.last_customer_message_at) : NaN;
    const hrs = isNaN(last) ? null : (Date.now() - last) / 36e5;
    chLine = '📱 Messaging ticket (' + ch + '): send from Agent Workspace — public comments through the Ticket API do NOT reach the customer.';
    if (ch === 'whatsapp') {
      if (hrs === null) chLine += ' Check the WhatsApp 24h window before replying.';
      else if (hrs > 24) chLine += ' ⏰ WhatsApp 24h window CLOSED (~' + Math.round(hrs) + 'h): first send template "reactivar_conversacion" (' + (d.reply_language === 'en' ? 'en' : 'es') + '), reply after the customer answers.';
      else chLine += ' WhatsApp window open (~' + Math.max(0, Math.round(24 - hrs)) + 'h left).';
    }
  }
  const lines = [
    '🤖 Nova Resolver · draft (v1.5) · ' + $now.setZone('America/Bogota').toFormat('dd LLL HH:mm') + ' COL' + (tk.revisit ? ' · re-check after new activity' : ''),
    'Owner: ' + tk.owner + ' · Domain: ' + tk.domain + ' · Confidence: ' + d.confidence,
    '• Ask: ' + (d.ask || '-'),
    '• Onsight: ' + (d.onsight_facts || 'not verified'),
    '• Aura knowledge used:' + (kb ? '\n' + kb : ' none'),
    '• Can we answer now? ' + (ANS[d.answerable] || d.answerable || '-'),
    d.missing_info ? '• Missing: ' + d.missing_info : '',
    '• Suggested action: ' + (d.suggested_action || '-'),
    '• Draft reply (' + (d.reply_language || '-') + '):\n"' + (d.draft_reply || '') + '"',
    d.risk_flags ? '⚠️ ' + d.risk_flags : '',
    chLine,
  ].filter(Boolean);
  const suggestText = scSuggest ? '💡 Suggested side conversation to ' + (TEAM[d.sc_team] || d.sc_team) + ' (NOT created' + (why.length ? ': ' + why.join(', ') : '') + ') — copy if useful:\nSubject: ' + (d.sc_subject || '') + '\n' + d.sc_body : '';
  const sc = scCreate ? { message: { subject: '[Ticket #' + tk.ticket_id + '] ' + (d.sc_subject || 'Transfer status check'), body: d.sc_body + '\n\nZendesk ticket #' + tk.ticket_id + ' · Transaction ID(s): ' + d.sc_transaction_ids + '\nThank you! 🙌', to: [{ support_group_id: 27679198971284 }] } } : null;
  // v1.4 auto-send: answerable=yes + confidence=high + no risk flags + guard words + a channel we can deliver to
  const TICKET_OK = ['email', 'web', 'api', 'mobile', 'mobile_sdk'];
  const SUNSHINE_OK = ['native_messaging', 'sunshine_conversations_api', 'whatsapp', 'sunshine_conversations_facebook_messenger', 'instagram_dm'];
  const txt = String(d.draft_reply || '');
  const GUARD = [/ofac|sanci[oó]n|sanction|\bvpn\b/i, /contrase(ñ|n)a temporal|temporary password/i, /\b(currencycloud|thunes|nium|rapyd|dlocal|airwallex|lead bank|evolve bank|column bank|circle|bridge\.xyz)\b/i,
    /\b\d+\s*(horas|hours|d[ií]as|days|minutos|minutes)\b(?![^.]*h[aá]biles|[^.]*business)/i, /\[|\{|<|TODO|XX/];
  const ffBad = /future fund/i.test(txt) && /\b(segur|ahorro|inter[eé]s|safe|savings|interest)/i.test(txt);
  const guardHit = GUARD.some(r => r.test(txt)) || ffBad;
  const lastMs = d.last_customer_message_at ? Date.parse(d.last_customer_message_at) : NaN;
  const waOpen = !isNaN(lastMs) && (Date.now() - lastMs) / 36e5 < 23;
  const replyNeeded = d.reply_needed !== false;
  let sendVia = 'none', autoWhy = [];
  if (!replyNeeded) sendVia = 'status_only';
  else if (TICKET_OK.includes(ch)) sendVia = 'ticket';
  else if (SUNSHINE_OK.includes(ch) && (ch !== 'whatsapp' || waOpen)) sendVia = 'sunshine';
  else autoWhy.push(ch === 'whatsapp' ? 'WhatsApp 24h window closed/unknown' : 'channel ' + ch + ' not supported');
  if (!tk.auto_send) autoWhy.push(tk.mode === 'backlog' ? 'auto-send off' : 'auto-send off');
  if (d.answerable !== 'yes') autoWhy.push('answerable=' + d.answerable);
  if (d.confidence !== 'high') autoWhy.push('confidence ' + d.confidence);
  if (d.risk_flags) autoWhy.push('risk flags');
  if (guardHit) autoWhy.push('draft failed the wording guard');
  if (replyNeeded && txt.length < 40) autoWhy.push('draft too short');
  const statusAfter = d.status_after_reply === 'pending' ? 'pending' : 'solved';
  const auto = autoWhy.length === 0 && sendVia !== 'none';
  const autoLine = auto
    ? (sendVia === 'status_only' ? '🚀 Auto: customer only acknowledged — no message sent, status → ' + statusAfter + '.' : '🚀 Auto-reply: Nova sends the draft below to the customer (' + (sendVia === 'sunshine' ? 'chat/WhatsApp' : 'email/web') + ') and sets status → ' + statusAfter + '.')
    : (d.answerable === 'yes' ? '✋ Not sent automatically: ' + autoWhy.join(', ') + '.' : '');
  const stamp = 'nova_res_' + $now.toUTC().toFormat('yyyyLLddHHmm');
  return JSON.stringify({ skip: false, ticket_id: tk.ticket_id, owner: tk.owner, domain: tk.domain, channel: ch,
    note_base: lines.join('\n'), suggest_text: suggestText, auto_line: autoLine,
    footer: auto ? 'Sent by Nova (answerable + high confidence). If something is off, follow up with the customer 🙌' : 'This is a draft — please validate before sending 🙌',
    auto: auto, send_via: sendVia,
    // v1.5: backlog sweep is "quiet" — nothing is written to the ticket unless Nova replies or opens a Payouts side conversation
    post_note: !tk.quiet || auto || scCreate, status_after: statusAfter, reply_text: txt, mode: tk.mode || 'scheduled',
    sc_create: scCreate, sc: sc, sc_suggested: scSuggest, sc_team: d.sc_team || 'none',
    answerable: d.answerable || '', confidence: d.confidence || '', reply_language: d.reply_language || '',
    ask: d.ask || '', kb_titles: (d.kb_used || []).map(k => k.title).join(' | '),
    stamp: stamp, add_tags: auto ? [stamp, 'nova_resolver_auto'] : [stamp], remove_tags: tk.old_stamps || [] });
})() }}

