// Sunshine conversation id of THIS ticket (deterministic, from its own audits — never from the model)
const ev = ($input.first()?.json?.audits || []).flatMap(a => a.events || []).filter(e => e.type === 'ChatStartedEvent');
const id = ev.length ? (ev[ev.length - 1].value || {}).conversation_id : null;
return [{ json: id ? { conversation_id: id } : { conversation_id: 'missing', conversation_error: 'no Sunshine conversation found in audits' } }];

// Rank Ada knowledge articles for a free-text query (BM25-lite over name + content). Input: the paginated
// /knowledge/articles responses (one item per page). Output: ONE item with the top matches, trimmed.
const q = String(($('When Called as KB Tool').first().json.query) || '');
const lang = String(($('When Called as KB Tool').first().json.language) || '').toLowerCase();
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
const STOP = new Set('a al algo como con de del el en es esta este la las lo los mi mis no o para por que se si su sus tu tus un una y yo me le the to of and or in on for is are my your how what why when can do does i it with from be have has not at this that an as by'.split(' '));
const toks = s => norm(s).split(/[^a-z0-9]+/).filter(w => w.length > 2 && !STOP.has(w));
const stem = w => w.length > 5 ? w.slice(0, 5) : w; // cheap stemming: transferencia/transferencias/transfer → trans... 
const qt = [...new Set(toks(q).map(stem))];
const arts = $input.all().flatMap(i => i.json.data || []).filter(a => a.enabled !== false);
const docs = arts.map(a => {
  const nt = toks(a.name).map(stem), ct = toks(a.content).map(stem);
  const tf = {}; for (const w of ct) tf[w] = (tf[w] || 0) + 1;
  return { a, nt: new Set(nt), tf, len: ct.length || 1 };
});
const N = docs.length, avg = docs.reduce((s, d) => s + d.len, 0) / (N || 1);
const df = {}; for (const w of qt) df[w] = docs.filter(d => d.tf[w] || d.nt.has(w)).length;
const scored = docs.map(d => {
  let s = 0;
  for (const w of qt) {
    const idf = Math.log(1 + (N - df[w] + 0.5) / (df[w] + 0.5));
    const f = d.tf[w] || 0;
    s += idf * (f * 2.2) / (f + 1.2 * (0.25 + 0.75 * d.len / avg));
    if (d.nt.has(w)) s += idf * 1.5; // title match bonus
  }
  const loc = norm(d.a.locale || d.a.language || '');
  if (lang && loc && !loc.startsWith(lang)) s *= 0.6; // prefer the customer's language
  return { s, d };
}).filter(x => x.s > 0).sort((x, y) => y.s - x.s).slice(0, 5);
return [{ json: { query: q, total_articles: N, results: scored.map(({ s, d }) => ({
  score: Math.round(s * 10) / 10, id: d.a.id, title: d.a.name, url: d.a.url || '', locale: d.a.locale || d.a.language || '',
  content: String(d.a.content || '').slice(0, 1800),
})) } }];
